1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	
5	/**
6	 * Works out an invoice's payment status from what has actually been paid against it, rather than the
7	 * owner flipping it by hand: PAID once payments cover the billed amount, PARTIAL once some (but not
8	 * all) is paid, otherwise the invoice's stored lifecycle status (e.g. a sent, unpaid invoice reads
9	 * SENT). Shared by the reads that surface an invoice's status.
10	 */
11	final class InvoiceStatus {
12	
13	    private InvoiceStatus() {
14	    }
15	
16	    static String derive(String storedStatus, BigDecimal amount, BigDecimal paid) {
17	        if (amount != null && amount.signum() > 0 && paid.compareTo(amount) >= 0) {
18	            return "PAID";
19	        }
20	        if (paid.signum() > 0) {
21	            return "PARTIAL";
22	        }
